// === Tab: mySketch ===
// by SamuelYAN
// more works //
// https://twitter.com/SamuelAnn0924
// https://www.instagram.com/samuel_yan_1990/

// reference: https://gorillasun.de/blog/Radial-Perlin-Noise-and-Generative-Tree-Rings
// reference: https://www.reddit.com/r/processing/comments/awzkgd/tree_rings_made_with_perlin_noise/

// Shape of TIME

let scale;
let t;
let mySize, radius;
var Stroke_Weight;
var Gear_Size;
var Turbulence;

// colors without alpha
const palettes = [
	["#4596c7", "#6d8370", "#e45240", "#21d3a4", "#3303f9"],
	["#5d565c", "#b41a1d", "#c0dee4", "#edb136", "#e07958"],
	["#7382ce", "#9fb7f4", "#12177d", "#9bb5e9", "#7486af"],
	["#1b1b1b", "#292929", "#f3f3f3", "#222222", "#ff0000"],
	["#eda492", "#d59c95", "#af3918", "#d9b6b5", "#853532"],
	["#f86fcd", "#97d183", "#240ce8", "#b0e298", "#7f37e8"],
	["#2E294E", "#541388", "#F1E9DA", "#FFD400", "#D90368"],
	["#a3ecff", "#7ebcff", "#3898ff", "#e0efff", "#fff0ab"],
	["#ffcd6d", "#ffb424", "#ffd700", "#90c700", "#eff6db"],
	["#e61919", "#800000", "#1c1c1c", "#d11507", "#fef9fb"],
	["#5930b1", "#b195d9", "#e6dbf3", "#e6e6fa", "#a260bf"]
]

/** OPC START **/
OPC.slider('Gears_of_time', Math.floor(Math.random() * 1000), 0, 1000, 10); //seed
OPC.slider('Gear_Rings', 50, 30, 60, 10);
OPC.slider('Era', 4, 0, palettes.length - 1, 1); // color
OPC.slider('Vicissitudes', 50, 50, 100, 1); // gear tooth
/** OPC END **/

let PGears_of_time = Gears_of_time;
let PGear_Rings = Gear_Rings;
let PEra = Era;
let PVicissitudes = Vicissitudes;

function setup() {
	randomSeed(Gears_of_time);
	noiseSeed(Gears_of_time);
	mySize = max(windowWidth, windowHeight);
	createCanvas(windowWidth, windowHeight);
	colorMode(HSB, 360, 100, 100, 100);
	background(9);
	noFill();
	t = random(TAU);
	scale = 1;
	Stroke_Weight = 2;
	Gear_Size = 3;
	Turbulence = 0.008;
}

function draw() {
	randomSeed(Gears_of_time);
	noiseSeed(Gears_of_time);
	radius = mySize / 5 * Gear_Size;
	Gear();

	if (PGears_of_time != Gears_of_time ||
		PGear_Rings != Gear_Rings ||
		PEra!= Era ||
		PVicissitudes != Vicissitudes) {

		PGears_of_time = Gears_of_time;
		PGear_Rings = Gear_Rings;
		PEra = Era;
		PVicissitudes = Vicissitudes;

		randomSeed(Gears_of_time);
		noiseSeed(Gears_of_time);
		background(9);
		Stroke_Weight = int(random(1, 5));
		Gear_Size = int(random(2.5, 10));
		Turbulence = random(0.005, 0.02);
	}
}

function Gear() {

	push();
	translate(width / 2, height / 2);
	let o_angle = random(TAU);

	for (let r = 0; r < radius; r += radius / Gear_Rings) {
		stroke(random(palettes[Era]));
		strokeCap(ROUND);
		rotate(o_angle + t);
		for (
			let a = -TAU / Vicissitudes; a < TAU + TAU / Vicissitudes; a += TAU / Vicissitudes
		) {
			let x = r * cos(a);
			let y = r * sin(a);
			let n = map(noise(x * Turbulence, y * Turbulence), 0, 1, 0, scale);
			stroke(random(palettes[Era]));
			strokeWeight(n * Stroke_Weight);
			line(x * n, y * n, x * (1 - n), y * (1 - n));
			stroke(str(random(palettes[Era])) + "1a");
			strokeWeight(n / 2);
			line(x * (1 - n), y * (1 - n), 0, 0);
		}
	}
	pop();
	t += TAU / 360 / int(random(2, 5)) / Gear_Rings;
}

function keyTyped() {
	if (key === "s" || key === "S") {
		saveCanvas("Shape of TIME_gear", "png");
	}
}

